import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.Ci_RTJJ5.js";const u=JSON.parse('{"title":"How other harnesses are built","description":"","frontmatter":{},"headers":[],"relativePath":"docs/designs.md","filePath":"docs/designs.md"}'),s={name:"docs/designs.md"};function i(n,t,h,d,c,l){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="how-other-harnesses-are-built" tabindex="-1">How other harnesses are built <a class="header-anchor" href="#how-other-harnesses-are-built" aria-label="Permalink to &quot;How other harnesses are built&quot;">​</a></h1><p>The course teaches one machine. These are four real ones, and what each is worth reading for. The point is not to copy them; it is to see the same seams at different scales.</p><table tabindex="0"><thead><tr><th>Project</th><th>Language</th><th>Size</th><th>Read it for</th></tr></thead><tbody><tr><td><a href="https://github.com/earendil-works/pi" target="_blank" rel="noreferrer">pi</a></td><td>TypeScript</td><td>about 11 packages</td><td>the complete event and extension model</td></tr><tr><td><a href="https://github.com/MichaelKinsy/PiG" target="_blank" rel="noreferrer">PiG</a></td><td>Go</td><td>a line-by-line port of pi</td><td>the same design in Go, with parity tests</td></tr><tr><td><a href="https://github.com/charmbracelet/crush" target="_blank" rel="noreferrer">crush</a></td><td>Go</td><td>about 49 internal packages</td><td>what Go wants to look like at scale</td></tr><tr><td><a href="https://github.com/vercel-labs/fx" target="_blank" rel="noreferrer">fx</a></td><td>Zig</td><td>719k lines, 667 files</td><td>the smallest concept count that still works</td></tr></tbody></table><h2 id="pi" tabindex="-1">pi <a class="header-anchor" href="#pi" aria-label="Permalink to &quot;pi&quot;">​</a></h2><p>The reference implementation of everything this course teaches, plus the parts it deliberately skips: extensions, a tree-shaped session, compaction as a session entry, thirty provider adapters, and a terminal UI.</p><p>Read these files in order.</p><table tabindex="0"><thead><tr><th>File</th><th>What it shows</th></tr></thead><tbody><tr><td><code>packages/agent/src/agent-loop.ts</code></td><td>the loop: stream, buffer calls, run them, append results, repeat</td></tr><tr><td><code>packages/agent/src/types.ts</code></td><td>the event union, and the before/after tool hooks</td></tr><tr><td><code>packages/ai/src/api/openai-completions.ts</code></td><td>the provider client you wrote in chapter 01, with retries and caching</td></tr><tr><td><code>packages/mcp/</code></td><td>a hand-rolled MCP client over stdio</td></tr><tr><td><code>docs/how-pi-works.md</code></td><td>the architecture in prose, without code</td></tr></tbody></table><h2 id="pig" tabindex="-1">PiG <a class="header-anchor" href="#pig" aria-label="Permalink to &quot;PiG&quot;">​</a></h2><p>pi rebuilt in Go as one binary, with a parity harness that runs the same scenario against both implementations and diffs the results.</p><p>Read it when you want to see the course&#39;s architecture in the language you are writing. Two things are worth more than the code: <code>test/parity/</code> is a working example of a harness that tests a harness, and <code>docs/parity/PORT_MAP.md</code> shows how to keep a port honest.</p><h2 id="crush" tabindex="-1">crush <a class="header-anchor" href="#crush" aria-label="Permalink to &quot;crush&quot;">​</a></h2><p>The most idiomatic Go harness. Its loop is not in the repository at all: it comes from <code>charm.land/fantasy</code>, which makes crush an adapter around a shared loop. That is worth knowing before you go looking for <code>loop.go</code>.</p><p>Read it for structure rather than for the loop.</p><table tabindex="0"><thead><tr><th>Package</th><th>What it shows</th></tr></thead><tbody><tr><td><code>internal/permission/</code></td><td>a permission service, rather than a hook</td></tr><tr><td><code>internal/agent/</code></td><td>coordination, tool dispatch, queueing</td></tr><tr><td><code>internal/mcp/</code></td><td>MCP through the official Go SDK</td></tr><tr><td><code>internal/lsp/</code></td><td>what a real editor integration costs</td></tr><tr><td><code>internal/ui/</code></td><td>a Bubble Tea interface over agent events</td></tr></tbody></table><h2 id="fx" tabindex="-1">fx <a class="header-anchor" href="#fx" aria-label="Permalink to &quot;fx&quot;">​</a></h2><p>The minimal end of the spectrum, and the best evidence for the claim that a harness is a library with injected capabilities rather than an application.</p><p>The marketing says 6.66 MiB. That number is a macOS arm64 build. Linux x86_64 is 13.39 MiB, and the source is larger than crush. What is genuinely smaller is the concept count: a host supplies instructions, tools, network, storage and permissions, and the core does the rest.</p><p>One measurement from it is worth carrying into your own work: a cold request was 23,884 bytes, and 15,560 of those were tool schemas. Sixty-five percent of a request was definitions, before any conversation existed. That is why chapter 07 counts both budgets.</p><h2 id="what-the-four-agree-on" tabindex="-1">What the four agree on <a class="header-anchor" href="#what-the-four-agree-on" aria-label="Permalink to &quot;What the four agree on&quot;">​</a></h2><ul><li><strong>One call, one result.</strong> A tool call resolves exactly once, including on failure.</li><li><strong>Results keep source order.</strong> Execution order is yours; append order is not.</li><li><strong>The model is behind a seam.</strong> Every one of them can be pointed at a different provider without touching the loop.</li><li><strong>Context is the scarce resource.</strong> They differ in how they bound it, not in whether they do.</li></ul><h2 id="what-they-do-that-this-course-does-not" tabindex="-1">What they do that this course does not <a class="header-anchor" href="#what-they-do-that-this-course-does-not" aria-label="Permalink to &quot;What they do that this course does not&quot;">​</a></h2><p>Extensions and plugins, a terminal UI beyond a chapter list, editor integration, image input, provider authentication, background subagents, and evaluation harnesses. <a href="./../chapters/where-next.html">Where next</a> lists which of those is worth building on top of what you have, and which is a different project.</p>',22)])])}const f=e(s,[["render",i]]);export{u as __pageData,f as default};
